script.text:
function load$GridReport$(g) {
	g.add_onRender(on$GridReport$Render);
	g._$k = [];
	g._$i = ['name_key_1']; // phan tu 1 la key dedupe — doi theo field khoa that
	g._$t = g._getColumnOrder('tag');
	g._$only_one = 0; // 1 = chi chon duoc 1 dong
	g.add_commandEvent(on$GridReport$ExecuteCommand);
	g.add_onResponseComplete(on$GridReport$ResponseComplete);
	g._$f = 'keys'; // memvar keys trong Filter — chi dung khi IN theo dong tick
}

function dispose$GridReport$(g) {
	g._$k = g._$i = g._$t = null;
	try {g.remove_onRender(on$GridReport$Render);} catch (ex) {}
	try {g.remove_onResponseComplete(on$GridReport$ResponseComplete);} catch (ex) {}
}
function on$GridReport$Render(sender, eventArgs) {
	var g = eventArgs.grid;
	if (g._hiddenFields) {
		var a = g._hiddenFields, h = '';
		for (var i = 0; i < a.length; i++) {
			setGridHiddenFields(g, a[i].Fields, a[i].Value);
			if (a[i].Value) h += (h == '' ? '' : ',') + a[i].Fields;
		}
		g._externalHiddenFields = h;
	}
	g._$k = [];
}
function setGridHiddenFields(g, c, v) {
	var a = c.split(',');
	for (var i = 0; i < a.length; i++) {
		g._setColumnVisible(g._getColumnOrder($func.trim(a[i])), !v);
	}
}
function on$GridReport$ExecuteCommand(sender, e) {
	var action = e.type.Action, g = sender;
	switch (action) {
		case 'Action1':
			if (!isCheck$Grid(g)) break;
			g.request(g, 'Action1', 'Action1', [['name_key_1', 'Infinite', arrField(g, 'name_key_1')]]);
			break;
		case 'Action2':
			if (!isCheck$Grid(g)) break;
			g.request(g, 'Action2', 'Action2', [['name_key_1', 'Infinite', arrField(g, 'name_key_1')]]);
			break;
		default:
			break;
	}
}
function on$GridReport$ResponseComplete(sender, e) {
	var g = e.object, context = e.type.Context, result = e.type.Result;
	switch (context) {
		case 'Action1':
		case 'Action2':
			$message.show(result[0].Value);
			g.goToPage(-1);
			break;
		default:
			break;
	}
}
function isCheck$Grid(g) {
	var msg = (g._language == 'v' ? 'Chưa có bản ghi nào được chọn, phải đánh dấu trước khi thực hiện chức năng này.' : 'No record selected, please select at least one record to process.');
	if (g._$k.length == 0) {
		$message.show(msg, String.format('$find(\'{0}\')._focusWhenTabChanged();', g.get_id()));
		return false;
	}
	return true;
}
function toggle$Grid(o) {
	var c = o.parentNode.parentNode.parentNode.id, g = $find($func.left(c, c.length - 11));
	if (!g._$only_one) {
		for (var r = 1; r <= g._rowCount; r++) {
			if (!g._getItem(r, g._$t).disabled) {
				var checked = addOrRemove(g, r);
				g._setItemValue(r, g._$t, !checked);
			}
		}
		init$ExportKey(g);
		if (g._rowCount <= 0) return;
		else {
			g._activeRow = g._rowCount;
			g._activeColumn = g._$t;
			g._activeCell = g._getItem(g._activeRow, g._activeColumn);
			g._focusWhenTabChanged();
		}
	}
}
function onChange$SelectedValue(o) {
	var a = o.id.split('_inputCell_'), g = o.grid;
	if (!g) g = $find(a[0]);
	var r = $func.getLocationCell(o)[0];
	addOrRemove(g, r);
	init$ExportKey(g);
	g._activeRow = a[1].split('.')[0];
	g._activeColumn = a[1].split('.')[1];
	g._activeCell = g._getItem(g._activeRow, g._activeColumn);
}
function addOrRemove(g, r) {
	var json = {}, key = g._$i[0], key_val = g._getItemValue(r, g._getColumnOrder(key));
	for (idx in g._$i) {
		var field = g._$i[idx];
		var val = g._getItemValue(r, g._getColumnOrder(field));
		json[field] = val;
	}
	var checked = g._$k.some(function (x) { return x[key] == key_val });
	if (checked)
		g._$k = g._$k.filter(function (x) { return x[key] != key_val });
	else {
		if (g._$only_one) g._$k = [];
		g._$k.push(json);
	}
	if (g._$only_one) fill$Grid(g);
	return checked;
}
function fill$Grid(g) {
	var key = g._$i[0];
	for (var i = 1; i <= g._rowCount; i++) {
		var key_val = g._getItemValue(i, g._getColumnOrder(key));
		var checked = g._$k.some(function (x) { return x[key] == key_val });
		g._setItemValue(i, g._$t, checked);
	}
}
function arrField(g, field) {
	return g._$k.map(function (item) { return item[field] });
}
function init$ExportKey(g, c) {
	var p = (c ? c : ''), keys = p + arrField(g, g._$i[0]).join(',') + p, v = g._filterMemvars, i = $func.findMemvarIndex(g._$f, v);
	if (i > -1) {
		var memvar = v[i];
		memvar.NewValue = memvar.Compressed ? $func.compress(keys) : keys;
	}
}
function refresh$Page(g) {
	g._$k = [];
	g.goToPage(-1);
}
function beforeDrillDown(g) {g._args.cancelEvent = !($func.trim(g._getItemValue(g._activeRow, g._activeColumn)));}
function formatDateView(c) {return String.format('{0}/{1}/{2}', c.substring(6, 8), c.substring(4, 6), c.substring(0, 4));}
